SELECT c.element AS cat, COUNT(DISTINCT ip) AS ips
FROM `dw-main-bronze.external.ipdsc__v1`, UNNEST(data_source_category_ids.list) c
WHERE dt BETWEEN '2026-06-04' AND '2026-06-17' AND data_source_id=35
  AND c.element IN (
    1000090114,1000090104,1000090094,1000090084,1000090074,1000090064,1000090054,1000090044,1000090034,1000090024,1000090014,
    1004602219,1004602229,1004602239,1004602249,1004602259,1004602269,1004602279,1004602289,1004602299,1004602309)
GROUP BY cat
